SELECT data_month, STRFTIME(data_month, '%b') AS month_label, COUNT(*) AS trip_count, AVG(fare_amount) AS avg_fare_amount, MEDIAN(fare_amount) AS median_fare_amount, AVG(total_amount) AS avg_total_amount, MEDIAN(total_amount) AS median_total_amount FROM tlc.taxi.yellow_trips WHERE data_month >= DATE '2026-01-01' AND data_month < DATE '2026-04-01' GROUP BY data_month ORDER BY data_month
